class Hero {
public:
  void equip(Item* item) { /* ... */ statsDirty_ = true; }
  void addBuff(Buff b)   { /* ... */ statsDirty_ = true; }
  const Stats& finalStats() {
    if (statsDirty_) {
      cached_ = computeStats(gear_, buffs_, talents_);
      statsDirty_ = false;
    }
    return cached_;
  }
private:
  bool  statsDirty_ = true;
  Stats cached_;
};

class TileMap {
public:
  // The ONLY way to change walkability.
  void setBlocked(int x, int y, bool blocked) {
    if (tiles_[y][x].blocked == blocked) return;
    tiles_[y][x].blocked = blocked;
    pathDirty_ = true;
  }
  bool isBlocked(int x, int y) const { return tiles_[y][x].blocked; }
private:
  Tile tiles_[H][W];
  bool pathDirty_ = true;
};

void GraphNode::setTransform(Transform local) {
  local_ = local;
  markDirty();
}

void GraphNode::markDirty() {
  if (dirty_) return;            // subtree already dirty
  dirty_ = true;
  for (int i = 0; i < numChildren_; i++)
    children_[i]->markDirty();
}

const Transform& GraphNode::worldTransform() {
  if (dirty_) {
    Transform parentWorld = parent_ ? parent_->worldTransform()
                                    : Transform::origin();
    world_ = local_.combine(parentWorld);
    dirty_ = false;
  }
  return world_;
}

void BaseSync::onRegionChanged(int region) {
  dirtyRegions_.set(region);
  if (!timerRunning_) startTimer(10.0);   // hysteresis
}

void BaseSync::flush() {               // timer, checkpoint, or onPause
  for (int r = 0; r < NUM_REGIONS; r++) {
    if (!dirtyRegions_.test(r)) continue;
    uploadAsync(r, snapshotRegion(r)); // copy, then send
    dirtyRegions_.reset(r);
  }
  timerRunning_ = false;
}
